#include "cfrienddialog.hpp"
#include <algorithm>
namespace mxh::ui{void cFriendDialog::AddFriend(FriendEntry f){if(f.id==0||f.name.empty())return;if(std::none_of(m_friends.begin(),m_friends.end(),[&](const auto&x){return x.id==f.id;}))m_friends.push_back(std::move(f));}bool cFriendDialog::RemoveFriend(std::uint32_t id){auto it=std::find_if(m_friends.begin(),m_friends.end(),[&](const auto&x){return x.id==id;});if(it==m_friends.end())return false;m_friends.erase(it);m_selected=static_cast<std::size_t>(-1);return true;}bool cFriendDialog::UpdateStatus(std::uint32_t id,FriendStatus s){for(auto&f:m_friends)if(f.id==id){f.status=s;return true;}return false;}bool cFriendDialog::Select(std::size_t i)noexcept{if(i>=m_friends.size())return false;m_selected=i;return true;}const FriendEntry* cFriendDialog::Selected()const noexcept{return m_selected<m_friends.size()?&m_friends[m_selected]:nullptr;}bool cFriendDialog::WhisperSelected(){auto*f=Selected();if(!f)return false;if(m_whisper)m_whisper(*f);return true;}}
